	},
	[10151181] = {
		id = 10151181,
		form_id = 1015,
		content = "哈……恐怕你并非有什么急事找我，而只是想看看我的「窘态」吧？",
		subtitle_id = 1181,
		team_hero_id_list = "",
		hide_word = 0,
