	},
	[10151191] = {
		id = 10151191,
		form_id = 1015,
		content = "呃……如果你把这儿掀个底朝天，我倒是会比较在意。",
		subtitle_id = 1191,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1015
	},
	[10151201] = {
		id = 10151201,
		form_id = 1015,
		content = "从这实用性极低的包装和华而不实的装饰看来，这是你给心有好感却无法明说的某人准备的礼物吧？——什么？送给我的？啊……",
		subtitle_id = 1201,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1015
	},
	[10151211] = {
		id = 10151211,
		form_id = 1015,
		content = "在人们的普遍认知中，像我这样性格的人似乎必然嗜酒成性。很可惜，这个普遍认知在我这里并不适用，或者说，只适用一半。",
		subtitle_id = 1211,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1015
	},
	[10151221] = {
		id = 10151221,
		form_id = 1015,
		content = "我对我们的初次见面处于任务场合抱有些遗憾。倘若你对我的第一印象来自于我审讯罪犯时的表现，那么在真正认识我后，你的心理变化一定会很有趣。",
		subtitle_id = 1221,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1015
	},
	[10151231] = {
		id = 10151231,
		form_id = 1015,
		content = "「叙述」是一件麻烦事，因为言语的速度并不能赶上我思考的速度。而且总有人思考的速度比我的语速还要慢，和那样的人交流可真是麻烦。所以我不是很喜欢解释我的行事理由。",
		subtitle_id = 1231,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1015
	},
	[10151241] = {
		id = 10151241,
		form_id = 1015,
		content = "重大犯罪对策部破案率冠军阿努比斯、备受瞩目的新人芭丝特，他们两个都曾是我的部下。这话听起来像在炫耀？你说是就是吧。——哎呀，你要是修正者，我可能真的会考虑把你招来我这儿。可惜你不是。",
		subtitle_id = 1241,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1015
	},
	[10151251] = {
		id = 10151251,
		form_id = 1015,
		content = "我犯过的唯一一个错误，就是将自己置于过高的地位藐视一切。我本以为「文明」枯燥无趣，但世上确实还有我看不穿的东西。比如你的道路，于我而言仍是一个不可清晰解释的谜团——让我在你身边多待一阵吧，兴许能找到答案呢。",
		subtitle_id = 1251,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1015
	},
	[10151301] = {
		id = 10151301,
		form_id = 1015,
		content = "为了迎合特定审美而创造的非实用性服装——真不错啊。穿着这个作战应该能有理由多吃一碗饭。",
		subtitle_id = 1301,
		team_hero_id_list = "",
		hide_word = 0,
