	},
	[10531071] = {
		id = 10531071,
		form_id = 1053,
		content = "闻道有先后，术业有专攻。吾能有所悟，当属你之功。",
		subtitle_id = 1071,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531081] = {
		id = 10531081,
		form_id = 1053,
		content = "寻大道至理，如拾级而上，越是登高行远，越觉道法无穷。小辈，你所见的，又是何处风景呢？",
		subtitle_id = 1081,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531091] = {
		id = 10531091,
		form_id = 1053,
		content = "人生当有多少境界？心绪也好，术业也罢，一时以为穷极吾所能为，眼前又豁然开朗。唯有不问终点，方能一直走下去吧。",
