	},
	[10531141] = {
		id = 10531141,
		form_id = 1053,
		content = "万物皆循其道，急有何用？先坐吧，吃完饭再说。",
		subtitle_id = 1141,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531151] = {
		id = 10531151,
		form_id = 1053,
		content = "无聊了？那吾给你讲个故事，从前有座山，山里有座庙……咳咳。",
		subtitle_id = 1151,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531211] = {
		id = 10531211,
		form_id = 1053,
		content = "修天道，习术法，讲的是借天地之势，顺万物之形。吾既与你相识，可看不得你动逆天而行的歪脑筋。",
		subtitle_id = 1211,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531221] = {
		id = 10531221,
		form_id = 1053,
		content = "吾日三省吾身，吃饭了没？吃饱了没？吃好了没？你也应当如此，别老是看着别人，反而忘了自己。",
		subtitle_id = 1221,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531231] = {
		id = 10531231,
		form_id = 1053,
		content = "光阴如涧水奔流，昼夜不息。与其临岸嗟叹，逐波空忙……不如捧起水洗把脸。既入此境，便安心品味，静观万象，得闲时……发个呆也好。",
		subtitle_id = 1231,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531241] = {
		id = 10531241,
		form_id = 1053,
		content = "春秋二百载，世事更迭，故人零落。惟日月相推，星辰轮转，往复如常……待它们也有了变化，再寻不到恒常之物，是否这人间的变化，吾便尽能放下了？",
		subtitle_id = 1241,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
	[10531251] = {
		id = 10531251,
		form_id = 1053,
		content = "吾一人度了不少岁月，逢凶则欣然除之，静好则闲散度日。如今倒想要寻个良伴，兴起时云游山水，揽晨霞而齐孤鹜；兴尽后搭一草庐，伺弄点瓜果鸡黍，换个三杯两盏……等那些要事了却，你得空否？",
		subtitle_id = 1251,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1053
	},
