	},
	[10532251] = {
		id = 10532251,
		form_id = 1053,
		content = "心胸很豁达，悟性也高，稍微点拨一下就能知道我在说什么，是个可塑之才。",
		subtitle_id = 2251,
		team_hero_id_list = "",
