	[10732251] = {
		id = 10732251,
		form_id = 1073,
		content = "管理员并不是修正者，但却能为了保护人们挺身而出。虚恒那时也多亏有管理员的帮助，不然的话……嗯，还是不提这些了。总之有机会的话，要好好招待管理员一顿大餐作为报答呢。",
		subtitle_id = 2251,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1073
	},
	[1073226102] = {
		id = 1073226102,
		form_id = 1073,
		content = "从小到大都是姐姐在保护我。无论什么样的坏人和麻烦的事情，姐姐都有办法对付……可她本不需这么坚强，一定是因为太勉强自己才变得不爱笑的，要是我能早点帮上姐姐的忙就好了。",
		subtitle_id = 226102,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1073
	},
	[1073226103] = {
		id = 1073226103,
		form_id = 1073,
		content = "孟章前辈虽然看起来散漫，实际上想得可细了，不愧是四方院代理。以前我在习题中出了点小错，都是他提前给我指出来。嘿嘿，要不然肯定会被老师说一顿。",
		subtitle_id = 226103,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1073
	},
	[1073226104] = {
		id = 1073226104,
		form_id = 1073,
		content = "在外界看来老师是一个冷漠理智的掌权者，是知识渊博科研技术高超的学者。但实际上老师的性格并没有他们所说的那样锋芒，她会给不小心在实验室睡着的我盖毯子，会给不小心出了错的实验员耐心的讲解错误，会蹲下来平视和小孩子对话……如果他们能够更加了解老师就好了。",
		subtitle_id = 226104,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 1073
	},
	[1073011011] = {
		id = 1073011011,
		form_id = 107301,
		content = "欢迎欢迎！走过路过不要错过，刺桐港特色小吃，要尝试一下吗？",
		subtitle_id = 101128,
		team_hero_id_list = "",
