		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109502
	},
	[1095031011] = {
		id = 1095031011,
		form_id = 109503,
		content = "没想到我也有这样心绪万千的一天。\n不过有你在，一切都是最好的。",
		subtitle_id = 101154,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[1095031141] = {
		id = 1095031141,
		form_id = 109503,
		content = "这片海从没像今天这么美过。\n管理员……\n是不是海也在为我们欣喜呢？",
		subtitle_id = 114153,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[1095031151] = {
		id = 1095031151,
		form_id = 109503,
		content = "那是……\n管理员你有看到吗？这里。\n听说海鸥是忠贞的鸟类，这应该也算……好兆头吧？",
		subtitle_id = 115153,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[1095031161] = {
		id = 1095031161,
		form_id = 109503,
		content = "嗯，管理员？\n最近常这样突然靠近，是因为时时都想在一起吗？",
		subtitle_id = 116107,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[1095031012] = {
		id = 1095031012,
		form_id = 109503,
		content = "以后的时光，都能像今天一样幸福就好了，管理员，也是这样想的吧？",
		subtitle_id = 101205,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[1095031162] = {
		id = 1095031162,
		form_id = 109503,
		content = "第一次觉得，海上缠绵的浪花，就像人的臂弯。\n一定是……太想靠近你的缘故。",
		subtitle_id = 116205,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[1095031163] = {
		id = 1095031163,
		form_id = 109503,
		content = "总觉得，管理员现在应该再过来一点才对。\n如果是爱情电影的话，此时此刻就应该在美满的定格中淡出了吧。",
		subtitle_id = 116305,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[1095031166] = {
		id = 1095031166,
		form_id = 109503,
		content = "执子之手，与子偕老。原来是这样的感觉……\n牵起对的人，就会想永远不分开，走到最后。",
		subtitle_id = 116605,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503140590] = {
		id = 109503140590,
		form_id = 109503,
		content = "丝线……象征着缘分的联结。\n管理员，我为你织就的这份心意。\n你有感受到吗？",
		subtitle_id = 140590,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503140591] = {
		id = 109503140591,
		form_id = 109503,
		content = "管理员，这种时候，就离我再近一点吧。像这样~\n你难道不想接触到，更多的我吗？\n无论是哪一面的我，都期待着你的探索。",
		subtitle_id = 140591,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503140592] = {
		id = 109503140592,
		form_id = 109503,
		content = "说好了，就让这根丝线永远缠绕着我们。\n从此不再和你分开。",
		subtitle_id = 140592,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503400301] = {
		id = 109503400301,
		form_id = 109503,
		content = "真是的……彩排的时候好好的，现在还是会心跳加速。\n管理员，接下来这段路，你可要把我拉紧了。",
		subtitle_id = 400301,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503400302] = {
		id = 109503400302,
		form_id = 109503,
		content = "长久以来，爱情、家庭都不在我的考虑范围内……因为有太多更重要的目标。\n但是遇见你以来，所有克制都失效了，只想靠你近一点、再近一点。\n管理员，从今往后的人生，请让我与你携手共度，好吗？",
		subtitle_id = 400302,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503400303] = {
		id = 109503400303,
		form_id = 109503,
		content = "这样，就是终身的许诺了。",
		subtitle_id = 400303,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503400304] = {
		id = 109503400304,
		form_id = 109503,
		content = "明明套上了指环，却感到了圆满和自由……\n心意，还真是不讲道理呢。",
		subtitle_id = 400304,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
	[109503400305] = {
		id = 109503400305,
		form_id = 109503,
		content = "以前总觉得，生活是属于一个人的拼图游戏。关于自我、人生的答案，只能由自己去追寻。",
		subtitle_id = 400305,
		team_hero_id_list = "",
		hide_word = 0,
		chara_id = 109503
	},
